update wf_approval_task
assignee_user_id = #{assigneeUserId}, original_assignee_user_id = #{originalAssigneeUserId}, owner_user_id = #{ownerUserId}, task_status = #{taskStatus}, delegated_to_user_id = #{delegatedToUserId}, parent_task_id = #{parentTaskId}, due_at = #{dueAt}, completed_at = #{completedAt},
where id = #{id}

update wf_approval_task
set task_status = #{taskStatus},
    completed_at = #{completedAt}
where process_instance_id = #{processInstanceId}
  and task_status in ('CREATED', 'PENDING')
